#[tokio::test]
async fn test_background_event_logging() {
    // Enqueues a background job that appends the posted event to shared state
    let expected_body = r#""#.to_string();
    let mut app = spikard::App::new();
    app.route(
        spikard::post("/background/events"),
        move |_ctx: spikard::RequestContext| {
            let body = expected_body.clone();
            async move {
                Ok(axum::http::Response::builder()
                    .status(202u16)
                    .header("content-type", r#"application/json"#)
                    .body(axum::body::Body::from(body))
                    .unwrap())
            }
        },
    )
    .unwrap();
    let router = app.into_router().unwrap();
    let server = axum_test::TestServer::new(router);
    let response = server
        .post("/background/events")
        .bytes(bytes::Bytes::copy_from_slice(r#"{"event":"alpha"}"#.as_bytes()))
        .await;
    assert_eq!(response.status_code().as_u16(), 202u16);
    assert_eq!(
        response.headers().get("content-type").and_then(|v| v.to_str().ok()),
        Some(r#"application/json"#),
        "unexpected value for header 'content-type'"
    );
}

